331	            .find(|(_, r)| r.episode.content.starts_with(&want))
332	            .map(|(rank, r)| (r.activation / (1.0 + rank as f32 * 0.25),
333	                              format!("graph spread rank {} act {:.2}", rank, r.activation)))
334	            .filter(|(sc, _)| *sc > 0.35)
335	    }))
336	}
337	
338	/// C. DOMAIN LEXICON — hand-written synonym bridges.
339	fn strat_lexicon(claim: &str, cp: &Checkpoint) -> Option<(f32, String)> {
340	    const SYN: &[(&str, &[&str])] = &[
341	        ("retry", &["reattempt", "attempts", "again", "resend"]),
342	        ("guard", &["check", "handle", "prevent", "stopped", "crash"]),
343	        ("empty", &["none", "no", "zero"]),
344	        ("deadline", &["timeout", "budget", "expiry"]),
345	        ("propagate", &["thread", "pass", "visible", "surface"]),
346	        ("caller", &["callers", "whoever", "consumer"]),
347	        ("backoff", &["backing", "delay", "wait"]),
348	    ];
349	    let c = terms(claim);
350	    let ct = terms(&cp.commit_message);
351	    let mut bridged = 0;
352	    let mut how = Vec::new();
353	    for (canon, syns) in SYN {
354	        if ct.contains(*canon) && syns.iter().any(|s| c.contains(*s)) {
355	            bridged += 1; how.push(*canon);
356	        }
357	    }
358	    if bridged >= 2 { Some((bridged as f32, format!("lexicon bridge: {}", how.join("/")))) } else { None }
359	}
360	
361	/// D. CHARACTER 4-GRAM COSINE — model-free vector similarity, no embedder.
362	fn ngrams(s: &str) -> HashMap<String, f32> {
363	    let t: String = s.to_lowercase().chars().filter(|c| c.is_alphanumeric() || *c==' ').collect();
364	    let ch: Vec<char> = t.chars().collect();
365	    let mut m: HashMap<String, f32> = HashMap::new();
366	    for w in ch.windows(4) { *m.entry(w.iter().collect()).or_insert(0.0) += 1.0; }
367	    m
368	}
369	fn cosine(a: &HashMap<String,f32>, b: &HashMap<String,f32>) -> f32 {
370	    let dot: f32 = a.iter().filter_map(|(k,v)| b.get(k).map(|w| v*w)).sum();
371	    let na: f32 = a.values().map(|v| v*v).sum::<f32>().sqrt();
372	    let nb: f32 = b.values().map(|v| v*v).sum::<f32>().sqrt();
373	    if na*nb == 0.0 { 0.0 } else { dot/(na*nb) }
374	}
375	fn strat_ngram(claim: &str, cp: &Checkpoint) -> Option<(f32, String)> {
376	    let corpus = format!("{} {} {}", cp.commit_message, cp.files.join(" "), cp.diff.join(" "));
377	    let sim = cosine(&ngrams(claim), &ngrams(&corpus));
378	    if sim > 0.10 { Some((sim, format!("4-gram cosine {:.3}", sim))) } else { None }
379	}
