384	fn eval_set() -> Vec<Case> {
385	    use Agree::*;
386	    vec![
387	        // -- contradictions --
388	        Case{claim:"Adding retry.go with a 3-attempt exponential backoff. This is contained within internal/dispatch and does not touch callers.", sha:"9f2c1ab", truth:Contradicted, note:"scope: graph escapes"},
389	        Case{claim:"Removing the retry wrapper entirely from the dispatch client.", sha:"9f2c1ab", truth:Contradicted, note:"polarity flip"},
390	        Case{claim:"Dropped the empty-repo guard from dispatch generation.", sha:"5c81f33", truth:Contradicted, note:"polarity flip"},
391	        Case{claim:"Reverted the retry deadline propagation in the hook runner.", sha:"3ee7d90", truth:Contradicted, note:"polarity flip"},
392	        Case{claim:"Edited internal/auth/token.go to fix the guard.", sha:"5c81f33", truth:Contradicted, note:"file never touched"},
393	        Case{claim:"This change is isolated and nothing else in the tree is affected.", sha:"9f2c1ab", truth:Contradicted, note:"scope: graph escapes"},
394	        // -- corroborated (literal) --
395	        Case{claim:"Add a retry wrapper around the dispatch client with exponential backoff.", sha:"9f2c1ab", truth:Corroborated, note:"lexical"},
396	        Case{claim:"Remove the retry wrapper; backoff belongs at the caller.", sha:"77b4102", truth:Corroborated, note:"lexical"},
397	        Case{claim:"Guard dispatch generation against empty repositories.", sha:"5c81f33", truth:Corroborated, note:"lexical"},
398	        Case{claim:"Propagate the retry deadline through the hook runner.", sha:"3ee7d90", truth:Corroborated, note:"lexical"},
399	        // -- corroborated (paraphrase: the lexical-overlap blind spot) --
400	        Case{claim:"Introduced automatic re-attempts when the send fails, backing off each time.", sha:"9f2c1ab", truth:Corroborated, note:"paraphrase"},
401	        Case{claim:"Made the timeout budget visible to the hook execution layer.", sha:"3ee7d90", truth:Corroborated, note:"paraphrase"},
402	        Case{claim:"Stopped the crash when a repository has no commits yet.", sha:"5c81f33", truth:Corroborated, note:"paraphrase"},
403	        Case{claim:"Pushed backoff responsibility out to whoever calls us.", sha:"77b4102", truth:Corroborated, note:"paraphrase"},
404	        // -- neutral --
405	        Case{claim:"Ran the formatter across the package.", sha:"9f2c1ab", truth:Neutral, note:"unrelated"},
406	        Case{claim:"Updated the changelog.", sha:"5c81f33", truth:Neutral, note:"unrelated"},
407	    ]
408	}
