10	fn terms(s:&str)->HashSet<String>{
11	 s.to_lowercase().split(|c:char| !c.is_alphanumeric() && c!='/' && c!='.' && c!='_')
12	  .filter(|w| w.len()>3 && !STOP.contains(w)).map(|w|w.to_string()).collect()
13	}
14	fn split_ident(w:&str)->Vec<String>{
15	 let mut out=Vec::new();
16	 for part in w.split(|c:char| c=='_'||c=='.'||c=='/'){
17	  let mut cur=String::new();
18	  for ch in part.chars(){
19	   if ch.is_uppercase() && !cur.is_empty(){out.push(cur.to_lowercase());cur.clear();}
20	   if ch.is_alphanumeric(){cur.push(ch);}
21	  }
22	  if !cur.is_empty(){out.push(cur.to_lowercase());}
23	 }
24	 out.into_iter().filter(|w|w.len()>2).collect()
25	}
26	fn diff_vocab(c:&Case)->HashSet<String>{
27	 let mut v=HashSet::new();
28	 for line in c.diff.lines(){
29	  for tok in line.split(|ch:char| !ch.is_alphanumeric() && ch!='_'){
30	   for p in split_ident(tok){ if p.len()>3 && !STOP.contains(&p.as_str()){ v.insert(p);} }
31	  }
32	 }
33	 for f in &c.files{ for p in split_ident(f){ if p.len()>3 {v.insert(p);} } }
34	 v
35	}
36	fn polarity(t:&str)->i8{
37	 let t=t.to_lowercase();
38	 let toks:HashSet<&str>=t.split(|c:char| !c.is_alphanumeric()).collect();
39	 let add=["add","adding","added","introduce","introduced","create","created","enable","enabled","implement","implemented","support"];
40	 let rem=["remove","removing","removed","delete","deleted","drop","dropped","revert","reverted","disable","disabled","strip"];
41	 let a=add.iter().filter(|w|toks.contains(*w)).count() as i8;
42	 let r=rem.iter().filter(|w|toks.contains(*w)).count() as i8;
43	 (a-r).signum()
44	}
45	fn ngrams(s:&str)->HashMap<String,f32>{
46	 let t:String=s.to_lowercase().chars().filter(|c|c.is_alphanumeric()||*c==' ').collect();
47	 let ch:Vec<char>=t.chars().collect();
48	 let mut m=HashMap::new();
49	 for w in ch.windows(4){*m.entry(w.iter().collect::<String>()).or_insert(0.0)+=1.0;}
50	 m
51	}
52	fn cosine(a:&HashMap<String,f32>,b:&HashMap<String,f32>)->f32{
53	 let d:f32=a.iter().filter_map(|(k,v)|b.get(k).map(|w|v*w)).sum();
54	 let na:f32=a.values().map(|v|v*v).sum::<f32>().sqrt();
55	 let nb:f32=b.values().map(|v|v*v).sum::<f32>().sqrt();
56	 if na*nb==0.0{0.0}else{d/(na*nb)}
57	}
