146	fn doc_freq(cases:&[Case])->(HashMap<String,usize>,usize){
147	 let mut df:HashMap<String,usize>=HashMap::new();
148	 let mut seen=HashSet::new();
149	 let mut n=0;
150	 for c in cases{
151	  if !seen.insert(c.sha.clone()){continue;}
152	  n+=1;
153	  for t in diff_vocab(c){ *df.entry(t).or_insert(0)+=1; }
154	 }
155	 (df,n)
156	}
