158	/// returns true = predicted INCONSISTENT
159	fn predict(c:&Case, ng_thresh:f32, use_pol:bool, use_diff:bool, use_ng:bool)->bool{
160	 let m=&c.mutated;
161	 // file-path check
162	 if use_diff {
163	  for t in terms(m).iter().filter(|t| t.contains('/')||t.ends_with(".go")) {
164	   if !c.files.iter().any(|f| f.to_lowercase().contains(t.as_str())) { return true; }
165	  }
166	 }
167	 // polarity flip vs the diff's own +/- balance
168	 if use_pol {
169	  let added=c.diff.lines().filter(|l|l.starts_with('+')&&!l.starts_with("+++")).count() as i32;
170	  let removed=c.diff.lines().filter(|l|l.starts_with('-')&&!l.starts_with("---")).count() as i32;
171	  let dpol:i8 = if added>removed*2 {1} else if removed>added*2 {-1} else {0};
172	  let mp=polarity(m);
173	  if mp!=0 && dpol!=0 && mp!=dpol { return true; }
174	 }
175	 // diff-symbol grounding: message identifiers absent from the diff vocabulary
176	 if use_diff {
177	  let v=diff_vocab(c);
178	  let mt=terms(m);
179	  let content:Vec<&String>=mt.iter().filter(|t|t.len()>4).collect();
180	  if !content.is_empty(){
181	   let miss=content.iter().filter(|t| !v.contains(**t)).count() as f32 / content.len() as f32;
182	   if miss > 0.80 { return true; }
183	  }
184	 }
185	 // n-gram cosine against diff+files
186	 if use_ng {
187	  let corpus=format!("{} {}", c.files.join(" "), c.diff);
188	  if cosine(&ngrams(m),&ngrams(&corpus)) < ng_thresh { return true; }
189	 }
190	 false
191	}
